require 'json';require 'fileutils';require 'set'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);assets=File.join(client,'assets');uuid_report=JSON.parse(File.read(File.join(root,'work/audit/cocos-uuid-reference-audit.json')));dynamic=JSON.parse(File.read(File.join(root,'work/audit/client-dynamic-load-graph.json')))
referenced=Set.new;Dir.glob(File.join(assets,'**/*.{prefab,scene,json}')).each{|path|File.binread(path).force_encoding('UTF-8').scrub.scan(/"__uuid__"\s*:\s*"([0-9a-fA-F-]{20,40})"/){|uuid|referenced<<uuid[0]}}
script_corpus=Dir.glob(File.join(assets,'**/*.{ts,js}')).map{|path|File.binread(path).force_encoding('UTF-8').scrub}.join("\n");bundle_roots=dynamic['bundleRoots'].to_set;extensions=%w[.prefab .scene .png .jpg .jpeg .webp .plist .atlas .ttf .otf .mp3 .ogg .wav .json];rows=[]
Dir.glob(File.join(assets,'**/*')).select{|path|File.file?(path)&&extensions.include?(File.extname(path).downcase)}.each do |path|
 meta=path+'.meta';uuid=nil;if File.file?(meta);begin;uuid=JSON.parse(File.read(meta))['uuid'];rescue JSON::ParserError;end;end
 relative=path.sub(client+'/','');base=File.basename(path,File.extname(path));in_bundle=bundle_roots.any?{|bundle|relative.start_with?(bundle+'/')};literal=script_corpus.match?(/(?<![A-Za-z0-9_])#{Regexp.escape(base)}(?![A-Za-z0-9_])/);direct=uuid&&referenced.include?(uuid);status=(direct||literal||in_bundle)?'reachable':'review-unused'
 rows<<{path:relative,type:File.extname(path).downcase,uuid:uuid,directReference:!!direct,pathLiteral:literal,dynamicBundleRoot:in_bundle,status:status}
