review=rows.select{|row|row[:status]=='review-unused'};out=File.join(root,'work/audit/dead12-client-resource-reachability.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate({task:'DEAD12',status:'passed-with-review',resourceCount:rows.size,reachableCount:rows.size-review.size,reviewUnusedCount:review.size,unresolvedDynamicExpressions:dynamic.dig('summary','unresolvedDynamicExpressions'),uuidIntegrity:uuid_report['summary'],resources:rows,limitations:['Computed runtime paths and Editor-only dependency resolution require final instrumented load capture before deletion.']})+"\n")
